#!/usr/bin/env python3
"""Round-59 residual handoff r1: 8 reviewer/critic seats attacking the committed build (ab6e100e) before the claims are measured.
Below the v1/v2 validator bands by design (prompt §6 item 2: residual checks go into one call of <= 8 reviewer/critic seats);
the taskCall is built in the same shape as the validator's (context + tasks[name, agent, task]) and written as r1-dispatch.json."""
import importlib.util, json, os
HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location("w1spec", os.path.join(HERE, "make_spec_w1.py"))
w1 = importlib.util.module_from_spec(spec); spec.loader.exec_module(w1)
BUILD = "ab6e100e442046006fa039315f5bd33bb516940b"
BASE = w1.BASE
L, W, SCR = w1.LANE, w1.W, w1.SCR
ctx = w1.CONTEXT.replace("Round-59 kake wave w1 (one v2 wave: build + attack items together).",
                         f"Round-59 kake residual handoff r1 (8 reviewer/critic seats; attack the committed build {BUILD} before the claims are measured).")
ctx = ctx.replace(".ufo/waves/round-59/w1/<Seat>.md", ".ufo/waves/round-59/r1/<Seat>.md").replace(".ufo/waves/round-59/w1/<Seat>.files/", ".ufo/waves/round-59/r1/<Seat>.files/")
ctx = ctx.replace("Counters are VERSION 1: wave 1 attacks them before any claim is measured; no seat scores an after-state.",
                  "Counters are VERSION 2 (contract.md § Counter versions; frozen at cdf089b1); you may run them at the build to attack them, but "
                  "the L1 takes the claim measurements.")
ctx += f" The build under attack is lane commit {BUILD}; wave-1 reports are in {W}/w1/. Never edit lane files: findings only."
items = [
 ("ReviewerEntrySignals", "reviewer", f"Sentence-level fidelity review of {L}/corpus/knowledge/crawler-identity-signals.md (at {BUILD}) against the retained page {W}/sources/S425.html (`python3 -B {W}/span_tools.py window S425`). Yardsticks: {W}/w1/ReviewerFidelityPrep.files/reference.md and the must-not list {W}/w1/CriticEntryOverreach.md. For every rendering and prose claim: supported / overreach / dropped qualifier (primarily, may, several) / wrong, with the page text. Check the recheck command (run its grep on the retained body) and cross-links (files exist). Report sections: `FINDINGS:` (line, entry text, page text, fix), `CLEAN LINES:`, `VERDICT:`."),
 ("ReviewerEntryVerification", "reviewer", f"Sentence-level fidelity review of {L}/corpus/knowledge/googlebot-verification.md (at {BUILD}) against {W}/sources/S426.html (`python3 -B {W}/span_tools.py window S426`), using {W}/w1/ReviewerFidelityPrep.files/reference.md and {W}/w1/CriticEntryOverreach.md. Check every rendering, the category table (masks, JSON file names), the four steps, the three worked examples byte-for-byte against the page's <pre> blocks, the five list links, and every [INFERENCE] tag. Report sections: `FINDINGS:` (line, entry text, page text, fix), `VERDICT:`."),
 ("ReviewerCorrection", "reviewer", f"Review the append-only correction in {L}/corpus/knowledge/crawler-identity.md at {BUILD} (`git -C {L} diff {BASE} {BUILD} -- corpus/knowledge/crawler-identity.md`): inserted lines only? Does every sentence hold against S425/S426 (span_tools window S425 / S426), does it keep what the old bullet got right, does it overstate (e.g. 'a server log records the requesting IP' — is that the page's statement or a general fact, and is it marked)? Does it render as part of the bullet in CommonMark? Report sections: `FINDINGS:` (sentence, support, fix), `VERDICT:`."),
 ("ReviewerAxisCells", "reviewer", f"Truth review of the three replaced SCORECARD axis-table evidence cells at {BUILD} (`git -C {L} show {BUILD}:SCORECARD.md | sed -n 15,19p`) and the `## Superseded axis-table evidence (round 59)` section at EOF. For every statement and every `A/B` number: open the cited receipt and confirm it says that (not merely contains the string); check that each cell neither inflates the legacy 10 nor understates what the receipts show; that the superseded section keeps the three base cells byte-exact (`git show {BASE}:SCORECARD.md | sed -n 17,19p`). Report sections: `FINDINGS:` (cell, statement, receipt evidence, verdict), `INFLATION:`, `VERDICT:`."),
 ("ReviewerResolverDiff", "reviewer", f"Code-review the landed tool change: `git -C {L} diff {BASE} {BUILD} -- scripts/id_resolver.py`. Check: HTML-comment and setext/thematic-break handling against CommonMark; symlink handling (revision: ls-tree modes, in-tree resolution with a bound; worktree: in-lane dir following with cycle protection, `_read_regular_inside` O_NONBLOCK + fstat S_ISREG + /proc/self/fd containment); registry containment; surrogateescape names; the toplevel rule; that working-tree results on the real lane are unchanged; that the source names neither `c57_idresolver_gate` nor `.ufo/` nor `reference(`. Run its selftest from a scratch copy (72 checks expected) and compare behaviour with the independent second candidate {W}/w1/ExecResolverFix2.files/id_resolver.py on 10 fixtures of your choice. Also read {W}/integration/tool-hole-probes.txt. Report sections: `FINDINGS:` (severity, line, input, fix), `SELFTEST:`, `DIFFERENTIAL:`, `VERDICT:`."),
 ("ReviewerLessonGate", "reviewer", f"Review {L}/corpus/lessons/round-59.md at {BUILD} for number and pointer drift: every count (rows 162->164, collisions 8, staged 129, quarantine 12 and its verdict union, mistakes N=7), every file pointer (exists at {BUILD}?), the two Gate lines (anchor equals the registry row anchor cell in {L}/corpus/SOURCES.md; quotes are page-unique article-block spans via span_tools; sha256/bytes equal sources/receipts.json), the two reject decision lines (re-open the cited pages with curl where a URL is given), and the considerthese queue's waited counts. Report sections: `FINDINGS:` (line, claim, observed, fix), `VERIFIED:`, `VERDICT:`."),
 ("CriticCountersV2", "critic", f"Attack the version-2 counters at the build {BUILD} in a shared clone under {SCR}/CriticCountersV2 (rules in context): C1 {W}/c59_axis_evidence.py (can a misleading or inflated axis cell still meet? a receipt of a met run cited for a number it does not report?), C3 {W}/c59_quote_truth.py (C9 attachment, chrome exclusion, `Last updated` source), C2 {W}/c59_resolver_cases.py (the holes in {W}/w1/CriticC2Cheat.md and {W}/w1/MutC2Gate.md: which remain under v2?). For each attack: the commit, the counter output, defect vs stated limit (contract.md § Counter versions lists the stated limits). Report sections: `ATTACKS:`, `NEW DEFECTS:`, `VERDICT:`."),
 ("ReviewerNoHarm", "reviewer", f"No-harm check of the build {BUILD} against earlier lane gates. In a shared clone at {BUILD} under {SCR}/ReviewerNoHarm run: .ufo/waves/round-58/c58_resolver_cases.py (--seed 58), c58_receipt_rewrites.py, c58_quote_truth.py; .ufo/waves/round-57/c57_idresolver_gate.py (--fleet /home/vgpnk/Projects/shokunin); .ufo/waves/round-55/c55_readme_index.py; .ufo/waves/round-56/c56_selftally.py (slow) — each with `--root <clone> --revision {BUILD}` (flags per each --help). Compare with the base values in {W}/w1/ExecHistoricalGates.md. A gate green at the base and red at {BUILD} is a harm unless SKILL.md marks it historical by design (c58_quote_truth now is) — say which. Also run `/home/vgpnk/Projects/shokunin/scripts/sources-census.sh validate --root /home/vgpnk/Projects/shokunin kake` (exit code + last lines). Report sections: `RUNS:` (gate, base, build, verdict), `HARMS:`, `VERDICT:`."),
]
tasks = [{"name": n, "agent": a, "task": w1.GODSPEED + t + f"\n\nLane bounds: leaf member — no subagent dispatch.\n\nReport: write your scoped findings to .ufo/waves/round-59/r1/{n}.md"} for n, a, t in items]
out = {"schema": "kake-r59-residual-dispatch-v1", "wave": "r1", "policy": "residual (<= 8 reviewer/critic seats; prompt §6 item 2)",
       "counts": {"spawn": len(tasks), "resume": 0, "total": len(tasks)}, "taskCall": {"context": ctx, "tasks": tasks}}
json.dump(out, open(os.path.join(HERE, "r1-dispatch.json"), "w"), indent=1, ensure_ascii=False)
print(len(tasks))
